# Generated by src/utils/setup_env.sh - source this before running cluster commands.
# If the Homebrew paths below do not match your machine, edit them or set the
# corresponding environment variables before sourcing this file.

# Resolve project root relative to this file (config/settings.sh -> project root)
if [ -z "${PROJECT_DIR:-}" ]; then
    PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
fi
export PROJECT_DIR

export JAVA_HOME="${JAVA_HOME:-/opt/homebrew/opt/openjdk@21}"
# Hadoop and Hive reach into JDK internals by reflection. JDK 17 and later
# enforce strong encapsulation, so these packages must be opened explicitly or
# the daemons and clients abort with InaccessibleObjectException.
export HADOOP_HOME="${HADOOP_HOME:-/opt/homebrew/opt/hadoop/libexec}"
export HADOOP_CONF_DIR="${HADOOP_CONF_DIR:-$HADOOP_HOME/etc/hadoop}"
export HIVE_HOME="${HIVE_HOME:-/opt/homebrew/opt/hive/libexec}"
export SPARK_HOME="${SPARK_HOME:-/opt/homebrew/opt/apache-spark/libexec}"
export HADOOP_MAPRED_HOME="$HADOOP_HOME"
export YARN_HOME="$HADOOP_HOME"
export HADOOP_OPTS="-Djava.awt.headless=true"
export HADOOP_CLIENT_OPTS="-Xmx1g"
export DATA_ROOT="${DATA_ROOT:-$PROJECT_DIR/data/hadoop-data}"
export PATH="$JAVA_HOME/bin:$HADOOP_HOME/bin:$HADOOP_HOME/sbin:$HIVE_HOME/bin:$SPARK_HOME/bin:$PATH"
